(7656278, 1156558, 113900, '<td valign="top">Great sky and I love the placement of the sun.  Nailed the exposure in my opinion.</td>', 'Great sky and I love the placement of the sun.  Nailed the exposure in my opinion.', '2020-03-24 13:33:14.000000', NULL, 0);
